 226		async newSession(options?: {
 227			parentSession?: string;
 228			setup?: (sessionManager: SessionManager) => Promise<void>;
 229			withSession?: (ctx: ReplacedSessionContext) => Promise<void>;
 230		}): Promise<{ cancelled: boolean }> {
 231			const beforeResult = await this.emitBeforeSwitch("new");
 232			if (beforeResult.cancelled) {
 233				return beforeResult;
 234			}
 235	
 236			const previousSessionFile = this.session.sessionFile;
 237			const sessionDir = this.session.sessionManager.getSessionDir();
 238			const sessionManager = this.session.sessionManager.isPersisted()
 239				? SessionManager.create(this.cwd, sessionDir)
 240				: SessionManager.inMemory(this.cwd);
 241			if (options?.parentSession) {
 242				sessionManager.newSession({ parentSession: options.parentSession });
 243			}
 244	
 245			await this.teardownCurrent("new", sessionManager.getSessionFile());
 246			this.apply(
 247				await this.createRuntime({
 248					cwd: this.cwd,
 249					agentDir: this.services.agentDir,
 250					sessionManager,
 251					sessionStartEvent: { type: "session_start", reason: "new", previousSessionFile },
 252				}),
 253			);
 254			if (options?.setup) {
 255				await options.setup(this.session.sessionManager);
 256				this.session.refreshContext();
 257			}
 258			await this.finishSessionReplacement(options?.withSession);
 259			return { cancelled: false };
 260		}
